package main

import (
	"fmt"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/callgraph"
	"golang.org/x/tools/go/callgraph/static"
	"golang.org/x/tools/go/packages"
)

type symbolKey struct {
	pkgPath  string
	name     string // func name or Type.Method
	declFile string
	declLine int
}

type callerInfo struct {
	callerKey string
	file      string
	line      int
	count     int // call sites from this caller
}

type fanInStats struct {
	key            symbolKey
	distinctCallers int
	totalCallSites  int
	callers         []callerInfo
}

func main() {
	repoRoot := "/bench/repo"
	if len(os.Args) > 1 {
		repoRoot = os.Args[1]
	}

	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesSizes |
			packages.NeedSyntax | packages.NeedTypesInfo | packages.NeedDeps,
		Dir: repoRoot,
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}
	for _, p := range pkgs {
		if len(p.Errors) > 0 {
			for _, e := range p.Errors {
				fmt.Fprintf(os.Stderr, "pkg %s: %v\n", p.PkgPath, e)
			}
		}
	}

	// Map declared symbols in internal/
	declMap := make(map[*token.Pos]symbolKey) // position of decl -> symbol
	internalDecls := make(map[symbolKey]bool)

	for _, pkg := range pkgs {
		if !strings.Contains(pkg.PkgPath, "/internal/") && !strings.HasSuffix(pkg.PkgPath, "/internal") {
			// also check path contains internal as directory
			if !strings.Contains(pkg.PkgPath, "internal") {
				continue
			}
		}
		// Only symbols declared in files under internal/ directory
		for _, file := range pkg.CompiledGoFiles {
			if !strings.Contains(file, "/internal/") {
				continue
			}
			// skip generated proto if needed - still internal declarations
		}
		if pkg.Types == nil {
			continue
		}
		for name, obj := range pkg.TypesInfo.Defs {
			if name == nil || obj == nil {
				continue
			}
			pos := obj.Pos()
			filename := pkg.Fset.File(pos).Name()
			if !strings.Contains(filename, "/internal/") {
				continue
			}
			line := pkg.Fset.Position(pos).Line

			symName := obj.Name()
			if recv := extractRecvName(pkg, obj); recv != "" {
				symName = recv + "." + symName
			}

			sk := symbolKey{
				pkgPath:  pkg.PkgPath,
				name:     symName,
				declFile: filename,
				declLine: line,
			}
			internalDecls[sk] = true
			declMap[&pos] = sk // won't work - pos is value
		}
	}

	// Rebuild decl map using object identity
	objToSym := make(map[string]symbolKey)
	for _, pkg := range pkgs {
		if pkg.Types == nil {
			continue
		}
		for name, obj := range pkg.TypesInfo.Defs {
			if name == nil || obj == nil {
				continue
			}
			pos := obj.Pos()
			filename := pkg.Fset.File(pos).Name()
			if !strings.Contains(filename, "/internal/") {
				continue
			}
			line := pkg.Fset.Position(pos).Line
			symName := obj.Name()
			if recv := extractRecvName(pkg, obj); recv != "" {
				symName = recv + "." + symName
			}
			sk := symbolKey{
				pkgPath:  pkg.PkgPath,
				name:     symName,
				declFile: filename,
				declLine: line,
			}
			objToSym[objID(obj)] = sk
		}
	}

	cg := static.CallGraph(pkgs)

	statsMap := make(map[symbolKey]*fanInStats)

	for _, node := range cg.Nodes {
		if node.Func == nil {
			continue
		}
		calleeID := objID(node.Func)
		sk, ok := objToSym[calleeID]
		if !ok {
			continue
		}
		if statsMap[sk] == nil {
			statsMap[sk] = &fanInStats{key: sk}
		}
	}

	// caller map per callee
	callerMaps := make(map[symbolKey]map[string]*callerInfo)

	for _, node := range cg.Nodes {
		if node.Func == nil {
			continue
		}
		calleeID := objID(node.Func)
		sk, ok := objToSym[calleeID]
		if !ok {
			continue
		}
		st := statsMap[sk]
		if callerMaps[sk] == nil {
			callerMaps[sk] = make(map[string]*callerInfo)
		}

		for _, edge := range node.In {
			callerNode := edge.Caller
			if callerNode.Func == nil {
				continue
			}
			// exclude self-calls (recursive / within same func)
			if callerNode.Func == node.Func {
				continue
			}
			callerObj := callerNode.Func
			callerKey := objID(callerObj)
			pos := edge.Site.Pos()
			file := callerNode.Func.Pkg().Files()[0].Name() // fallback
			if pos.IsValid() {
				file = pkgs[0].Fset.Position(pos).Filename
				// find correct fset
				for _, p := range pkgs {
					if p.Fset.File(pos) != nil {
						file = p.Fset.Position(pos).Filename
						break
					}
				}
			}
			line := 0
			if pos.IsValid() {
				for _, p := range pkgs {
					if p.Fset.File(pos) != nil {
						line = p.Fset.Position(pos).Line
						break
					}
				}
			}

			if callerMaps[sk][callerKey] == nil {
				cfn := callerObj.Name()
				if recv := extractRecvFromFunc(callerObj); recv != "" {
					cfn = recv + "." + cfn
				}
				callerMaps[sk][callerKey] = &callerInfo{
					callerKey: callerObj.Pkg().Path() + "/" + cfn,
					file:      file,
					line:      line,
				}
			}
			callerMaps[sk][callerKey].count++
			st.totalCallSites++
		}
	}

	for sk, cm := range callerMaps {
		st := statsMap[sk]
		st.distinctCallers = len(cm)
		for _, ci := range cm {
			st.callers = append(st.callers, *ci)
		}
		sort.Slice(st.callers, func(i, j int) bool {
			return st.callers[i].count > st.callers[j].count
		})
	}

	var allStats []*fanInStats
	for _, st := range statsMap {
		allStats = append(allStats, st)
	}

	sort.Slice(allStats, func(i, j int) bool {
		if allStats[i].distinctCallers != allStats[j].distinctCallers {
			return allStats[i].distinctCallers > allStats[j].distinctCallers
		}
		return allStats[i].totalCallSites > allStats[j].totalCallSites
	})

	fmt.Println("=== TOP 20 by DISTINCT CALLERS (fan-in) ===")
	for i, st := range allStats {
		if i >= 20 {
			break
		}
		fmt.Printf("%d. %s.%s @ %s:%d | distinct_callers=%d total_call_sites=%d\n",
			i+1, st.key.pkgPath, st.key.name, st.key.declFile, st.key.declLine,
			st.distinctCallers, st.totalCallSites)
		for j, c := range st.callers {
			if j >= 5 {
				fmt.Printf("   ... and %d more callers\n", len(st.callers)-5)
				break
			}
			fmt.Printf("   caller: %s (%d sites) e.g. %s:%d\n", c.callerKey, c.count, c.file, c.line)
		}
	}

	// Also sort by total call sites
	sort.Slice(allStats, func(i, j int) bool {
		if allStats[i].totalCallSites != allStats[j].totalCallSites {
			return allStats[i].totalCallSites > allStats[j].totalCallSites
		}
		return allStats[i].distinctCallers > allStats[j].distinctCallers
	})

	fmt.Println("\n=== TOP 20 by TOTAL CALL SITES ===")
	for i, st := range allStats {
		if i >= 20 {
			break
		}
		fmt.Printf("%d. %s.%s @ %s:%d | distinct_callers=%d total_call_sites=%d\n",
			i+1, st.key.pkgPath, st.key.name, st.key.declFile, st.key.declLine,
			st.distinctCallers, st.totalCallSites)
	}

	if len(allStats) > 0 {
		top := allStats[0]
		fmt.Printf("\nTOP BY CALL SITES: %s.%s @ %s:%d\n", top.key.pkgPath, top.key.name, top.key.declFile, top.key.declLine)
	}
}

