success.beforeFullFileContent:
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"go/ast"
	"go/token"
	"go/types"

	"golang.org/x/tools/go/packages"
)

type symbolKey struct {
	pkgPath  string
	name     string
	declFile string
	declLine int
}

func (s symbolKey) String() string {
	return fmt.Sprintf("%s.%s", s.pkgPath, s.name)
}

type callerKey struct {
	pkgPath string
	name    string
}

func (c callerKey) String() string {
	return fmt.Sprintf("%s.%s", c.pkgPath, c.name)
}

type callerStat struct {
	key   callerKey
	file  string
	line  int
	count int
}

type fanInStats struct {
	sym             symbolKey
	distinctCallers int
	totalCallSites  int
	callers         []callerStat
}

func main() {
	repoRoot := "/bench/repo"
	if len(os.Args) > 1 {
		repoRoot = os.Args[1]
	}

	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesSizes |
			packages.NeedSyntax | packages.NeedTypesInfo | packages.NeedDeps,
		Dir: repoRoot,
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}
	for _, p := range pkgs {
		for _, e := range p.Errors {
			fmt.Fprintf(os.Stderr, "pkg %s: %v\n", p.PkgPath, e)
		}
	}

	fset := pkgs[0].Fset

	// Map internal declarations: types.Object -> symbolKey
	internalObjs := make(map[types.Object]symbolKey)
	for _, pkg := range pkgs {
		if pkg.TypesInfo == nil {
			continue
		}
		for _, obj := range pkg.TypesInfo.Defs {
			if obj == nil {
				continue
			}
			pos := obj.Pos()
			if !pos.IsValid() {
				continue
			}
			filename := fset.File(pos).Name()
			if !isInternalDeclFile(filename, repoRoot) {
				continue
			}
			if !isCallable(obj) {
				continue
			}
			sk := symbolKey{
				pkgPath:  pkg.PkgPath,
				name:     symbolName(obj),
				declFile: filename,
				declLine: fset.Position(pos).Line,
			}
			internalObjs[obj] = sk
		}
	}

	// Fan-in stats keyed by symbolKey
	stats := make(map[symbolKey]*fanInStats)
	callerMaps := make(map[symbolKey]map[callerKey]*callerStat)

	initStats := func(sk symbolKey) {
		if stats[sk] == nil {
			stats[sk] = &fanInStats{sym: sk}
			callerMaps[sk] = make(map[callerKey]*callerStat)
		}
	}

	for _, pkg := range pkgs {
		if pkg.TypesInfo == nil || pkg.Syntax == nil {
			continue
		}
		info := pkg.TypesInfo

		for _, file := range pkg.Syntax {
			ast.Inspect(file, func(n ast.Node) bool {
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}

				calleeObj, callerObj := resolveCall(info, call)
				if calleeObj == nil {
					return true
				}

				sk, ok := internalObjs[calleeObj]
				if !ok {
					return true
				}

				// Exclude self-calls (recursive)
				if callerObj != nil && callerObj == calleeObj {
					return true
				}

				initStats(sk)
				st := stats[sk]
				st.totalCallSites++

				pos := call.Pos()
				callFile := fset.Position(pos).Filename
				callLine := fset.Position(pos).Line

				var ck callerKey
				if callerObj != nil {
					ck = callerKey{pkgPath: callerObj.Pkg().Path(), name: symbolName(callerObj)}
				} else {
					ck = callerKey{pkgPath: "?", name: "?"}
				}

				if callerMaps[sk][ck] == nil {
					callerMaps[sk][ck] = &callerStat{key: ck, file: callFile, line: callLine}
				}
				callerMaps[sk][ck].count++

				return true
			})
		}
	}

	for sk, cm := range callerMaps {
		st := stats[sk]
		st.distinctCallers = len(cm)
		for _, cs := range cm {
			st.callers = append(st.callers, *cs)
		}
		sort.Slice(st.callers, func(i, j int) bool {
			return st.callers[i].count > st.callers[j].count
		})
	}

	var all []*fanInStats
	for _, st := range stats {
		all = append(all, st)
	}

	// Sort by distinct callers (fan-in)
	sort.Slice(all, func(i, j int) bool {
		if all[i].distinctCallers != all[j].distinctCallers {
			return all[i].distinctCallers > all[j].distinctCallers
		}
		return all[i].totalCallSites > all[j].totalCallSites
	})

	fmt.Printf("Internal declarations analyzed: %d\n", len(internalObjs))
	fmt.Printf("Internal symbols with inbound calls: %d\n\n", len(all))

