package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"go/ast"
	"go/types"

	"golang.org/x/tools/go/packages"
)

type symbolKey struct {
	pkgPath  string
	name     string
	declFile string
	declLine int
}

func (s symbolKey) String() string {
	return fmt.Sprintf("%s.%s", s.pkgPath, s.name)
}

type callerKey struct {
	pkgPath string
	name    string
}

func (c callerKey) String() string {
	return fmt.Sprintf("%s.%s", c.pkgPath, c.name)
}

type callerStat struct {
	key   callerKey
	file  string
	line  int
	count int
}

type fanInStats struct {
	sym             symbolKey
	distinctCallers int
	totalCallSites  int
	callers         []callerStat
}

func main() {
	repoRoot := "/bench/repo"
	if len(os.Args) > 1 {
		repoRoot = os.Args[1]
	}

	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesSizes |
			packages.NeedSyntax | packages.NeedTypesInfo | packages.NeedDeps,
		Dir: repoRoot,
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}
	for _, p := range pkgs {
		for _, e := range p.Errors {
			fmt.Fprintf(os.Stderr, "pkg %s: %v\n", p.PkgPath, e)
		}
	}

	fset := pkgs[0].Fset

	internalObjs := make(map[types.Object]symbolKey)
	for _, pkg := range pkgs {
		if pkg.TypesInfo == nil {
			continue
		}
		for _, obj := range pkg.TypesInfo.Defs {
			if obj == nil {
				continue
			}
			pos := obj.Pos()
			if !pos.IsValid() {
				continue
			}
			filename := fset.File(pos).Name()
			if !isInternalDeclFile(filename, repoRoot) {
				continue
			}
			if _, ok := obj.(*types.Func); !ok {
				continue
			}
			sk := symbolKey{
				pkgPath:  pkg.PkgPath,
				name:     symbolName(obj),
				declFile: filename,
				declLine: fset.Position(pos).Line,
			}
			internalObjs[obj] = sk
		}
	}

	stats := make(map[symbolKey]*fanInStats)
	callerMaps := make(map[symbolKey]map[callerKey]*callerStat)

	initStats := func(sk symbolKey) {
		if stats[sk] == nil {
			stats[sk] = &fanInStats{sym: sk}
			callerMaps[sk] = make(map[callerKey]*callerStat)
		}
	}

	for _, pkg := range pkgs {
		if pkg.TypesInfo == nil || pkg.Syntax == nil {
			continue
		}
		info := pkg.TypesInfo

		for _, file := range pkg.Syntax {
			var funcStack []types.Object

			ast.Inspect(file, func(n ast.Node) bool {
				if n == nil {
					return true
				}

				switch fn := n.(type) {
				case *ast.FuncDecl:
					if obj, ok := info.Defs[fn.Name]; ok {
						funcStack = append(funcStack, obj)
					}
				case *ast.FuncLit:
					// anonymous func - no Defs entry for name, skip caller tracking
					funcStack = append(funcStack, nil)
				}

				if call, ok := n.(*ast.CallExpr); ok {
					calleeObj := resolveCallee(info, call)
					if calleeObj == nil {
						return true
					}
					sk, ok := internalObjs[calleeObj]
					if !ok {
						return true
					}

					var callerObj types.Object
					if len(funcStack) > 0 {
						callerObj = funcStack[len(funcStack)-1]
					}
					if callerObj != nil && callerObj == calleeObj {
						return true
					}

					initStats(sk)
					st := stats[sk]
					st.totalCallSites++

					pos := call.Pos()
					callFile := fset.Position(pos).Filename
					callLine := fset.Position(pos).Line

					var ck callerKey
					if callerObj != nil {
						ck = callerKey{pkgPath: callerObj.Pkg().Path(), name: symbolName(callerObj)}
					} else {
						ck = callerKey{pkgPath: "<init/top-level>", name: filepath.Base(callFile)}
					}

					if callerMaps[sk][ck] == nil {
						callerMaps[sk][ck] = &callerStat{key: ck, file: callFile, line: callLine}
					}
					callerMaps[sk][ck].count++
				}

				return true
			})

			// Fix stack: ast.Inspect doesn't give exit events, need separate walk
		}
	}

	// Re-walk with proper stack using ast.Walk
	for _, pkg := range pkgs {
		if pkg.TypesInfo == nil || pkg.Syntax == nil {
			continue
		}
		info := pkg.TypesInfo
		for _, file := range pkg.Syntax {
			walkWithStack(fset, info, file, internalObjs, stats, callerMaps, initStats)
		}
	}

	for sk, cm := range callerMaps {
		st := stats[sk]
		st.distinctCallers = len(cm)
		for _, cs := range cm {
			st.callers = append(st.callers, *cs)
		}
		sort.Slice(st.callers, func(i, j int) bool {
			return st.callers[i].count > st.callers[j].count
		})
	}

	var all []*fanInStats
	for _, st := range stats {
		all = append(all, st)
	}

	sort.Slice(all, func(i, j int) bool {
		if all[i].distinctCallers != all[j].distinctCallers {
			return all[i].distinctCallers > all[j].distinctCallers
		}
		return all[i].totalCallSites > all[j].totalCallSites
	})

	fmt.Printf("Internal func/method declarations: %d\n", len(internalObjs))
	fmt.Printf("Internal symbols with inbound calls: %d\n\n", len(all))

	fmt.Println("=== TOP 30 by DISTINCT CALLERS (fan-in) ===")
	for i, st := range all {
		if i >= 30 {
			break
		}
		fmt.Printf("%d. %s @ %s:%d | distinct_callers=%d total_call_sites=%d\n",
			i+1, st.sym.String(), st.sym.declFile, st.sym.declLine,
			st.distinctCallers, st.totalCallSites)
		for j, c := range st.callers {
			if j >= 8 {
				fmt.Printf("   ... +%d more callers\n", len(st.callers)-8)
				break
			}
			fmt.Printf("   %s (%d sites) e.g. %s:%d\n", c.key.String(), c.count, c.file, c.line)
		}
	}

	sort.Slice(all, func(i, j int) bool {
		if all[i].totalCallSites != all[j].totalCallSites {
			return all[i].totalCallSites > all[j].totalCallSites
		}
		return all[i].distinctCallers > all[j].distinctCallers
	})

	fmt.Println("\n=== TOP 30 by TOTAL CALL SITES ===")
	for i, st := range all {
		if i >= 30 {
			break
		}
		fmt.Printf("%d. %s @ %s:%d | distinct_callers=%d total_call_sites=%d\n",
			i+1, st.sym.String(), st.sym.declFile, st.sym.declLine,
			st.distinctCallers, st.totalCallSites)
	}
}

type walkState struct {
	fset          *tokenFileSet
	info          *types.Info
	internalObjs  map[types.Object]symbolKey
	stats         map[symbolKey]*fanInStats
	callerMaps    map[symbolKey]map[callerKey]*callerStat
	initStats     func(symbolKey)
	funcStack     []types.Object
}

// tokenFileSet alias to avoid importing go/token in type - use interface
type tokenFileSet interface {
	Position(pos interface{ IsValid() bool }) struct {
		Filename string
		Line     int
	}
}

func walkWithStack(
	fset interface {
		Position(pos interface{ IsValid() bool }) struct {
			Filename string
			Line     int
		}
	},
	info *types.Info,
	file *ast.File,
	internalObjs map[types.Object]symbolKey,
	stats map[symbolKey]*fanInStats,
	callerMaps map[symbolKey]map[callerKey]*callerStat,
	initStats func(symbolKey),
) {
	var stack []types.Object

	var visit func(ast.Node) bool
	visit = func(n ast.Node) bool {
		if n == nil {
			return false
		}

		switch fn := n.(type) {
		case *ast.FuncDecl:
			if obj, ok := info.Defs[fn.Name]; ok {
				stack = append(stack, obj)
			} else {
				stack = append(stack, nil)
			}
			for _, c := range fn.Body.List {
				ast.Inspect(c, func(child ast.Node) bool {
					if child == nil {
						return false
					}
					if _, ok := child.(*ast.FuncDecl); ok {
						return false
					}
					if f, ok := child.(*ast.FuncLit); ok {
						stack = append(stack, nil)
						if f.Body != nil {
							for _, stmt := range f.Body.List {
								ast.Inspect(stmt, visitLeaf(info, fset, internalObjs, stats, callerMaps, initStats, &stack))
							}
						}
						stack = stack[:len(stack)-1]
						return false
					}
					if call, ok := child.(*ast.CallExpr); ok {
						recordCall(info, fset, call, internalObjs, stats, callerMaps, initStats, stack)
					}
					return true
				})
			}
			stack = stack[:len(stack)-1]
			return false
		}
		return true
	}

	// Simpler: use ast.Inspect with manual stack on FuncDecl enter/exit via wrapper
	walkFile(fset, info, file, internalObjs, stats, callerMaps, initStats)
}

func walkFile(
	fset interface {
		Position(pos interface{ IsValid() bool }) struct {
			Filename string
			Line     int
		}
	},
	info *types.Info,
	file *ast.File,
	internalObjs map[types.Object]symbolKey,
	stats map[symbolKey]*fanInStats,
	callerMaps map[symbolKey]map[callerKey]*callerStat,
	initStats func(symbolKey),
) {
	type frame struct {
		node ast.Node
		obj  types.Object
	}
	var stack []frame

	ast.Inspect(file, func(n ast.Node) bool {
		if n == nil {
			// pop until we find matching - ast.Inspect doesn't support this
			return true
		}
		return true
	})

	// Use ast.Walk with custom visitor
	v := &funcVisitor{
		fset:         fset,
		info:         info,
		internalObjs: internalObjs,
		stats:        stats,
		callerMaps:   callerMaps,
		initStats:    initStats,
	}
	ast.Walk(v, file)
}

type funcVisitor struct {
	fset         interface {
		Position(pos interface{ IsValid() bool }) struct {
			Filename string
			Line     int
		}
	}
	info         *types.Info
	internalObjs map[types.Object]symbolKey
	stats        map[symbolKey]*fanInStats
	callerMaps   map[symbolKey]map[callerKey]*callerStat
	initStats    func(symbolKey)
	stack        []types.Object
}

func (v *funcVisitor) Visit(n ast.Node) ast.Visitor {
	if n == nil {
		return nil
	}

	switch fn := n.(type) {
	case *ast.FuncDecl:
		obj, _ := v.info.Defs[fn.Name]
		v.stack = append(v.stack, obj)
		return v
	case *ast.FuncLit:
		v.stack = append(v.stack, nil)
		return v
	case *ast.CallExpr:
		recordCall(v.info, v.fset, fn, v.internalObjs, v.stats, v.callerMaps, v.initStats, v.stack)
		return v
	}
	return v
}

// pop stack when leaving func - need Exit visitor pattern
// ast.Walk doesn't have exit - use inspector from golang.org/x/tools/go/ast/inspector

func visitLeaf(...) ast.Inspector { return nil } // remove dead code

func recordCall(
	info *types.Info,
	fset interface {
		Position(pos interface{ IsValid() bool }) struct {
			Filename string
			Line     int
		}
	},
	call *ast.CallExpr,
	internalObjs map[types.Object]symbolKey,
	stats map[symbolKey]*fanInStats,
	callerMaps map[symbolKey]map[callerKey]*callerStat,
	initStats func(symbolKey),
	stack []types.Object,
) {
	calleeObj := resolveCallee(info, call)
	if calleeObj == nil {
		return
	}
	sk, ok := internalObjs[calleeObj]
	if !ok {
		return
	}

	var callerObj types.Object
	if len(stack) > 0 {
		callerObj = stack[len(stack)-1]
	}
	if callerObj != nil && callerObj == calleeObj {
		return
	}

	initStats(sk)
	st := stats[sk]
	st.totalCallSites++

	pos := call.Pos()
	p := fset.Position(pos)
	callFile := p.Filename
	callLine := p.Line

	var ck callerKey
	if callerObj != nil {
		ck = callerKey{pkgPath: callerObj.Pkg().Path(), name: symbolName(callerObj)}
	} else {
		ck = callerKey{pkgPath: "<top-level>", name: callFile}
	}

	if callerMaps[sk][ck] == nil {
		callerMaps[sk][ck] = &callerStat{key: ck, file: callFile, line: callLine}
	}
	callerMaps[sk][ck].count++
}

func isInternalDeclFile(filename, repoRoot string) bool {
	rel, err := filepath.Rel(repoRoot, filename)
	if err != nil {
		return strings.Contains(filename, "/internal/")
	}
	return strings.HasPrefix(rel, "internal/") || strings.Contains(rel, "/internal/")
}

func symbolName(obj types.Object) string {
	if fn, ok := obj.(*types.Func); ok {
		sig, ok := fn.Type().(*types.Signature)
		if !ok {
			return fn.Name()
		}
		if recv := sig.Recv(); recv != nil {
			recvType := recv.Type()
			typeName := types.TypeString(recvType, func(*types.Package) string { return "" })
			typeName = strings.TrimPrefix(typeName, "*")
			return typeName + "." + fn.Name()
		}
		return fn.Name()
	}
	return obj.Name()
}

func resolveCallee(info *types.Info, call *ast.CallExpr) types.Object {
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		if obj, ok := info.Uses[fun]; ok {
			if _, ok := obj.(*types.Func); ok {
				return obj
			}
		}
	case *ast.SelectorExpr:
		if sel, ok := info.Selections[fun]; ok {
			return sel.Obj()
		}
		if obj, ok := info.Uses[fun.Sel]; ok {
			if _, ok := obj.(*types.Func); ok {
				return obj
			}
		}
	}
	return nil
}

