	}
}

func (ctx *analyzeCtx) walkDecl(decl ast.Decl) {
	switch d := decl.(type) {
	case *ast.FuncDecl:
		obj, _ := ctx.info.Defs[d.Name]
		ctx.funcStack = append(ctx.funcStack, obj)
		if d.Body != nil {
			ctx.walkBlock(d.Body)
		}
		ctx.funcStack = ctx.funcStack[:len(ctx.funcStack)-1]
	case *ast.GenDecl:
		for _, spec := range d.Specs {
			ctx.walkSpec(spec)
		}
	}
}

func (ctx *analyzeCtx) walkSpec(spec ast.Spec) {
	// var init functions etc.
}

func (ctx *analyzeCtx) walkBlock(block *ast.BlockStmt) {
	for _, stmt := range block.List {
		ctx.walkStmt(stmt)
	}
}

func (ctx *analyzeCtx) walkStmt(stmt ast.Stmt) {
	switch s := stmt.(type) {
	case *ast.BlockStmt:
		ctx.walkBlock(s)
	case *ast.IfStmt:
		if s.Init != nil {
			ctx.walkStmt(s.Init)
		}
		ctx.walkBlock(s.Body)
		if s.Else != nil {
			ctx.walkStmt(s.Else)
		}
	case *ast.ForStmt:
		if s.Init != nil {
			ctx.walkStmt(s.Init)
		}
		if s.Body != nil {
			ctx.walkBlock(s.Body)
		}
	case *ast.RangeStmt:
		if s.Body != nil {
			ctx.walkBlock(s.Body)
		}
	case *ast.SwitchStmt:
		if s.Init != nil {
			ctx.walkStmt(s.Init)
		}
		ctx.walkBlock(s.Body)
	case *ast.TypeSwitchStmt:
		if s.Init != nil {
			ctx.walkStmt(s.Init)
		}
		ctx.walkBlock(s.Body)
	case *ast.SelectStmt:
		ctx.walkBlock(s.Body)
	case *ast.AssignStmt:
		for _, expr := range s.Rhs {
			ctx.walkExpr(expr)
		}
		for _, expr := range s.Lhs {
			ctx.walkExpr(expr)
		}
	case *ast.ExprStmt:
		ctx.walkExpr(s.X)
	case *ast.ReturnStmt:
		for _, expr := range s.Results {
			ctx.walkExpr(expr)
		}
	case *ast.GoStmt:
		ctx.walkExpr(s.Call)
	case *ast.DeferStmt:
		ctx.walkExpr(s.Call)
	case *ast.SendStmt:
		ctx.walkExpr(s.Value)
	case *ast.IncDecStmt:
		ctx.walkExpr(s.X)
	case *ast.LabeledStmt:
		ctx.walkStmt(s.Stmt)
	case *ast.CaseClause:
		for _, expr := range s.List {
			ctx.walkExpr(expr)
		}
		for _, stmt := range s.Body {
			ctx.walkStmt(stmt)
		}
	case *ast.CommClause:
		if s.Comm != nil {
			ctx.walkStmt(s.Comm)
		}
		for _, stmt := range s.Body {
			ctx.walkStmt(stmt)
		}
	}
}

func (ctx *analyzeCtx) walkExpr(expr ast.Expr) {
	switch e := expr.(type) {
	case *ast.CallExpr:
		ctx.recordCall(e)
		ctx.walkExpr(e.Fun)
		for _, arg := range e.Args {
			ctx.walkExpr(arg)
		}
	case *ast.FuncLit:
		ctx.funcStack = append(ctx.funcStack, nil)
		if e.Body != nil {
			ctx.walkBlock(e.Body)
		}
		ctx.funcStack = ctx.funcStack[:len(ctx.funcStack)-1]
	case *ast.UnaryExpr:
		ctx.walkExpr(e.X)
	case *ast.BinaryExpr:
		ctx.walkExpr(e.X)
		ctx.walkExpr(e.Y)
	case *ast.SelectorExpr:
		ctx.walkExpr(e.X)
	case *ast.IndexExpr:
		ctx.walkExpr(e.X)
		ctx.walkExpr(e.Index)
	case *ast.IndexListExpr:
		ctx.walkExpr(e.X)
		for _, idx := range e.Indices {
			ctx.walkExpr(idx)
		}
	case *ast.SliceExpr:
		ctx.walkExpr(e.X)
		if e.Low != nil {
			ctx.walkExpr(e.Low)
		}
		if e.High != nil {
			ctx.walkExpr(e.High)
		}
		if e.Max != nil {
			ctx.walkExpr(e.Max)
		}
	case *ast.TypeAssertExpr:
		ctx.walkExpr(e.X)
	case *ast.CompositeLit:
		for _, elt := range e.Elts {
			switch v := elt.(type) {
			case ast.Expr:
				ctx.walkExpr(v)
			case *ast.KeyValueExpr:
				ctx.walkExpr(v.Key)
				ctx.walkExpr(v.Value)
			}
		}
	case *ast.ParenExpr:
		ctx.walkExpr(e.X)
	case *ast.StarExpr:
		ctx.walkExpr(e.X)
	}
}

func (ctx *analyzeCtx) recordCall(call *ast.CallExpr) {
	calleeObj := resolveCallee(ctx.info, call)
	if calleeObj == nil {
		return
	}
	sk, ok := ctx.internalObjs[calleeObj]
	if !ok {
		return
	}

	var callerObj types.Object
	if len(ctx.funcStack) > 0 {
		callerObj = ctx.funcStack[len(ctx.funcStack)-1]
	}
	if callerObj != nil && callerObj == calleeObj {
		return
	}

	ctx.initStats(sk)
	st := ctx.stats[sk]
	st.totalCallSites++

	pos := call.Pos()
	callFile := ctx.fset.Position(pos).Filename
	callLine := ctx.fset.Position(pos).Line

	var ck callerKey
	if callerObj != nil {
		ck = callerKey{pkgPath: callerObj.Pkg().Path(), name: symbolName(callerObj)}
	} else {
		ck = callerKey{pkgPath: "<top-level>", name: callFile}
	}

	if ctx.callerMaps[sk][ck] == nil {
		ctx.callerMaps[sk][ck] = &callerStat{key: ck, file: callFile, line: callLine}
	}
	ctx.callerMaps[sk][ck].count++
}

func isInternalDeclFile(filename, repoRoot string) bool {
	rel, err := filepath.Rel(repoRoot, filename)
	if err != nil {
		return strings.Contains(filename, "/internal/")
	}
	return strings.HasPrefix(rel, "internal/")
}

func symbolName(obj types.Object) string {
	fn, ok := obj.(*types.Func)
	if !ok {
		return obj.Name()
	}
	sig, ok := fn.Type().(*types.Signature)
	if !ok || sig.Recv() == nil {
		return fn.Name()
	}
	recvType := sig.Recv().Type()
	typeName := types.TypeString(recvType, func(*types.Package) string { return "" })
	typeName = strings.TrimPrefix(typeName, "*")
	return typeName + "." + fn.Name()
}

func resolveCallee(info *types.Info, call *ast.CallExpr) types.Object {
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		if obj, ok := info.Uses[fun]; ok {
			if _, ok := obj.(*types.Func); ok {
				return obj
			}
		}
	case *ast.SelectorExpr:
		if sel, ok := info.Selections[fun]; ok {
			obj := sel.Obj()
			if _, ok := obj.(*types.Func); ok {
				return obj
			}
		}
		if obj, ok := info.Uses[fun.Sel]; ok {
			if _, ok := obj.(*types.Func); ok {
				return obj
			}
		}
	}
	return nil
}

